fn prime_num(n: u64) -> bool {
    if n < 2 {
        return false; // This case won't happen as per the problem statement
    }
    if n == 2 {
        return true; // 2 is the only even prime number
    }
    if n % 2 == 0 {
        return false; // Exclude all even numbers greater than 2
    }
    
    let limit = (n as f64).sqrt() as u64; // Calculate the square root of n
    for k in 3..=limit {
        if n % k == 0 {
            return false; // Found a divisor
        }
    }
    
    true // No divisors found, n is prime
}